import{G as a,b as e,c as r,ae as o}from"./chunks/framework.zvXX7P8V.js";const d=JSON.parse('{"title":"GitHub 热门 AI 项目（2026 年第 39 周）","description":"","frontmatter":{"title":"GitHub 热门 AI 项目（2026 年第 39 周）","date":"2026/9/21","author":"花木凋零成兰","tags":["GitHub","AI","周刊","Agent"],"hiddenCover":true},"headers":[],"relativePath":"GitHub相关/2026/GitHub热门AI项目（2026年第39周）.md","filePath":"GitHub相关/2026/GitHub热门AI项目（2026年第39周）.md","lastUpdated":1791379802000}'),n={name:"GitHub相关/2026/GitHub热门AI项目（2026年第39周）.md"};function i(l,t,s,g,h,c){return e(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1789948800000"},[...t[0]||(t[0]=[o('<h1 id="github-热门-ai-项目-2026-年第-39-周" tabindex="-1">GitHub 热门 AI 项目（2026 年第 39 周） <a class="header-anchor" href="#github-热门-ai-项目-2026-年第-39-周" aria-label="Permalink to &quot;GitHub 热门 AI 项目（2026 年第 39 周）&quot;">​</a></h1><blockquote><p>数据来源：GitHub Trending 周榜（2026 年第 39 周）。Star 数为周榜快照值，周增量为当周新增数据，适合观察趋势。</p></blockquote><p>本周主线：<strong>代码评审与上下文工程成为 Agent 的新战场</strong>——阿里开源 open-code-review 单周飙涨超 1.5 万 Star 登顶，把&quot;确定性流水线 + LLM Agent&quot;的混合评审架构推到台前；与此同时，上下文压缩（context-mode）、harness 调优（ECC）、并行 Agent 编排（orca、worktrunk）共同指向同一个命题：让 Agent 跑得稳、跑得省、跑得多。</p><h2 id="项目清单" tabindex="-1">项目清单 <a class="header-anchor" href="#项目清单" aria-label="Permalink to &quot;项目清单&quot;">​</a></h2><h3 id="_1-open-code-review-alibaba-open-code-review" tabindex="-1">1. Open Code Review（alibaba/open-code-review） <a class="header-anchor" href="#_1-open-code-review-alibaba-open-code-review" aria-label="Permalink to &quot;1. Open Code Review（alibaba/open-code-review）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/alibaba/open-code-review" target="_blank" rel="noreferrer">https://github.com/alibaba/open-code-review</a></li><li><strong>Star 数</strong>：38,363（本周 +15,028）</li><li><strong>项目简介</strong>：阿里大规模实战打磨的代码评审工具：确定性流水线 + LLM Agent 混合架构，支持行级精准评论，内置 NPE、线程安全、XSS、SQL 注入等多语言规则集，兼容 OpenAI 与 Anthropic。</li><li><strong>本周热度亮点</strong>：本周全站增长第一、单周飙涨超 1.5 万 Star，大厂开源的&quot;AI 代码评审&quot;标杆项目。</li><li><strong>技术栈</strong>：Go</li></ul><h3 id="_2-ecc-affaan-m-ecc" tabindex="-1">2. ECC（affaan-m/ECC） <a class="header-anchor" href="#_2-ecc-affaan-m-ecc" aria-label="Permalink to &quot;2. ECC（affaan-m/ECC）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/affaan-m/ECC" target="_blank" rel="noreferrer">https://github.com/affaan-m/ECC</a></li><li><strong>Star 数</strong>：263,710（本周 +6,265）</li><li><strong>项目简介</strong>：Agent harness 性能优化系统：技能、直觉、记忆、安全与研究优先开发，兼容 Claude Code、Codex、Opencode、Cursor 等。</li><li><strong>本周热度亮点</strong>：长期霸榜的性能调优层，本周继续放量增长，Agent 运行效率成为可量化优化的对象。</li><li><strong>技术栈</strong>：JavaScript</li></ul><h3 id="_3-i-have-adhd-ayghri-i-have-adhd" tabindex="-1">3. i-have-adhd（ayghri/i-have-adhd） <a class="header-anchor" href="#_3-i-have-adhd-ayghri-i-have-adhd" aria-label="Permalink to &quot;3. i-have-adhd（ayghri/i-have-adhd）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/ayghri/i-have-adhd" target="_blank" rel="noreferrer">https://github.com/ayghri/i-have-adhd</a></li><li><strong>Star 数</strong>：49,219（本周 +5,589）</li><li><strong>项目简介</strong>：让编码 Agent 不再把答案埋在长篇输出里的技能，面向 ADHD 的简明输出范式。</li><li><strong>本周热度亮点</strong>：连续第二周高速增长，&quot;Agent 输出可读性&quot;从痛点变成标配诉求。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_4-orca-stablyai-orca" tabindex="-1">4. Orca（stablyai/orca） <a class="header-anchor" href="#_4-orca-stablyai-orca" aria-label="Permalink to &quot;4. Orca（stablyai/orca）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/stablyai/orca" target="_blank" rel="noreferrer">https://github.com/stablyai/orca</a></li><li><strong>Star 数</strong>：73,564（本周 +5,404）</li><li><strong>项目简介</strong>：面向多 Agent 并行协作的 ADE（Agent Development Environment），可成批调度编码 Agent 并行作业。</li><li><strong>本周热度亮点</strong>：把&quot;同时跑一队 Agent&quot;做成产品级工作台，并行编排从脚本技巧升级为开发环境能力。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_5-weknora-tencent-weknora" tabindex="-1">5. WeKnora（Tencent/WeKnora） <a class="header-anchor" href="#_5-weknora-tencent-weknora" aria-label="Permalink to &quot;5. WeKnora（Tencent/WeKnora）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/Tencent/WeKnora" target="_blank" rel="noreferrer">https://github.com/Tencent/WeKnora</a></li><li><strong>Star 数</strong>：27,970（本周 +4,867）</li><li><strong>项目简介</strong>：开源 LLM 知识平台：把原始文档转成可查询的 RAG 知识与智能体。</li><li><strong>本周热度亮点</strong>：腾讯开源的企业级 RAG 方案冲榜，知识库 + Agent 仍是落地最刚需的组合。</li><li><strong>技术栈</strong>：Go</li></ul><h3 id="_6-agent-reach-panniantong-agent-reach" tabindex="-1">6. Agent-Reach（Panniantong/Agent-Reach） <a class="header-anchor" href="#_6-agent-reach-panniantong-agent-reach" aria-label="Permalink to &quot;6. Agent-Reach（Panniantong/Agent-Reach）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/Panniantong/Agent-Reach" target="_blank" rel="noreferrer">https://github.com/Panniantong/Agent-Reach</a></li><li><strong>Star 数</strong>：83,831（本周 +3,914）</li><li><strong>项目简介</strong>：给 AI Agent 装上&quot;看整个互联网的眼睛&quot;：可读取与搜索 Twitter、Reddit 等平台内容。</li><li><strong>本周热度亮点</strong>：Agent 联网检索能力持续走热，信息获取广度成为 Agent 实用性的关键一环。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_7-agent-skills-addyosmani-agent-skills" tabindex="-1">7. Agent Skills（addyosmani/agent-skills） <a class="header-anchor" href="#_7-agent-skills-addyosmani-agent-skills" aria-label="Permalink to &quot;7. Agent Skills（addyosmani/agent-skills）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/addyosmani/agent-skills" target="_blank" rel="noreferrer">https://github.com/addyosmani/agent-skills</a></li><li><strong>Star 数</strong>：97,665（本周 +3,445）</li><li><strong>项目简介</strong>：面向 AI 编码 Agent 的生产级工程技能集。</li><li><strong>本周热度亮点</strong>：知名前端工程者出品的技能库，Skills 生态继续向&quot;高质量、可复用&quot;演进。</li><li><strong>技术栈</strong>：JavaScript</li></ul><h3 id="_8-humanizer-blader-humanizer" tabindex="-1">8. Humanizer（blader/humanizer） <a class="header-anchor" href="#_8-humanizer-blader-humanizer" aria-label="Permalink to &quot;8. Humanizer（blader/humanizer）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/blader/humanizer" target="_blank" rel="noreferrer">https://github.com/blader/humanizer</a></li><li><strong>Star 数</strong>：50,612（本周 +3,024）</li><li><strong>项目简介</strong>：去除文本中 AI 生成痕迹的 Agent 技能。</li><li><strong>本周热度亮点</strong>：与 no-ai-slop 共同构成&quot;AI 输出治理&quot;赛道，连续多周稳居增长榜。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_9-markitdown-microsoft-markitdown" tabindex="-1">9. MarkItDown（microsoft/markitdown） <a class="header-anchor" href="#_9-markitdown-microsoft-markitdown" aria-label="Permalink to &quot;9. MarkItDown（microsoft/markitdown）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/microsoft/markitdown" target="_blank" rel="noreferrer">https://github.com/microsoft/markitdown</a></li><li><strong>Star 数</strong>：185,937（本周 +2,767）</li><li><strong>项目简介</strong>：把各类文件与 Office 文档转换为 Markdown 的 Python 工具。</li><li><strong>本周热度亮点</strong>：LLM 数据摄入的事实标准工具，连续回榜印证文档解析与 RAG 前置处理的旺盛需求。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_10-hyperframes-heygen-com-hyperframes" tabindex="-1">10. HyperFrames（heygen-com/hyperframes） <a class="header-anchor" href="#_10-hyperframes-heygen-com-hyperframes" aria-label="Permalink to &quot;10. HyperFrames（heygen-com/hyperframes）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/heygen-com/hyperframes" target="_blank" rel="noreferrer">https://github.com/heygen-com/hyperframes</a></li><li><strong>Star 数</strong>：51,951（本周 +2,498）</li><li><strong>项目简介</strong>：写 HTML，渲染视频——为 Agent 构建的视频渲染框架。</li><li><strong>本周热度亮点</strong>：多模态生成的代表项目，把&quot;HTML → 视频&quot;做成 Agent 友好的渲染管线。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_11-no-ai-slop-petergyang-no-ai-slop" tabindex="-1">11. no-ai-slop（petergyang/no-ai-slop） <a class="header-anchor" href="#_11-no-ai-slop-petergyang-no-ai-slop" aria-label="Permalink to &quot;11. no-ai-slop（petergyang/no-ai-slop）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/petergyang/no-ai-slop" target="_blank" rel="noreferrer">https://github.com/petergyang/no-ai-slop</a></li><li><strong>Star 数</strong>：10,812（本周 +2,134）</li><li><strong>项目简介</strong>：清除 20 多种&quot;AI 味&quot;写作模式的 Agent 技能。</li><li><strong>本周热度亮点</strong>：&quot;去 AI 味&quot;从单点工具变成方法论集合，与 humanizer 形成合围。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_12-claude-code-anthropics-claude-code" tabindex="-1">12. Claude Code（anthropics/claude-code） <a class="header-anchor" href="#_12-claude-code-anthropics-claude-code" aria-label="Permalink to &quot;12. Claude Code（anthropics/claude-code）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/anthropics/claude-code" target="_blank" rel="noreferrer">https://github.com/anthropics/claude-code</a></li><li><strong>Star 数</strong>：147,103（本周 +1,999）</li><li><strong>项目简介</strong>：常驻终端的智能编码 Agent，能理解代码库、执行任务并处理 Git 工作流。</li><li><strong>本周热度亮点</strong>：头部编码 Agent 持续在榜，其生态内的技能与插件（如 knowledge-work-plugins）同步升温。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h2 id="本周趋势总结" tabindex="-1">本周趋势总结 <a class="header-anchor" href="#本周趋势总结" aria-label="Permalink to &quot;本周趋势总结&quot;">​</a></h2><ol><li><strong>AI 代码评审成新战场</strong>：alibaba/open-code-review 以&quot;确定性流水线 + LLM Agent&quot;混合架构登顶单周增长榜，大厂开始把内部打磨多年的评审能力开源，Agent 从&quot;写代码&quot;延伸到&quot;审代码&quot;。</li><li><strong>上下文与运行效率成为硬指标</strong>：context-mode（上下文窗口压缩）、ECC（harness 调优）、worktrunk（并行 worktree）集中上榜，Agent 的成本与稳定性取代&quot;能力炫技&quot;成为工程焦点。</li><li><strong>并行 Agent 编排走向产品化</strong>：orca 把&quot;一队 Agent 并行开工&quot;做成开发环境，配合 worktree 管理，多 Agent 并行从脚本拼装升级为工作流基础设施。</li><li><strong>输出治理赛道持续扩容</strong>：humanizer、no-ai-slop、i-have-adhd 稳定霸榜，去 AI 味、结论先行、反冗长已成 Agent 输出的基础质量线。</li><li><strong>知识层与检索层仍是刚需</strong>：Tencent/WeKnora 的 RAG 知识平台、Agent-Reach 的联网检索、microsoft/markitdown 的文档摄入，构成&quot;Agent 的外部大脑&quot;三件套。</li></ol><blockquote><p>注：以上 Star 数与周增量为 GitHub Trending 周榜快照值，仅供参考。</p></blockquote>',31)])])}const b=a(n,[["render",i]]);export{d as __pageData,b as default};
